},
"my_vector_2": {
"type": "knn_vector",
"dimension": 2,
"space_type": "cosine",
"method": {
"name": "hnsw",
"engine": "faiss",
"parameters": {
"ef_construction": 128,
"m": 24
}
}
}
}
}
}
Unsupported example: Adding S3 vector engine after index creation
The following approach is not supported and will fail.
PUT my-first-s3vector-index
{
"settings": {
"index": {
"knn": true
}
}
}
PUT my-first-s3vector-index/_mapping
{
"properties": {
"my_vector_1": {
"type": "knn_vector",
"dimension": 2,
"space_type": "l2",
"method": {
"engine": "s3vector"
}
},
